  function compressAndPrepareImage(file, maxDimension = 1500, quality = 0.85) {
    return new Promise((resolve, reject) => {
      if (!file) return reject(new Error("유효한 이미지 파일이 아닙니다."));
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          let width = img.naturalWidth || img.width;
          let height = img.naturalHeight || img.height;
          if (width > maxDimension || height > maxDimension) {
            if (width > height) {
              height = Math.round(height * maxDimension / width);
              width = maxDimension;
            } else {
              width = Math.round(width * maxDimension / height);
              height = maxDimension;
            }
          }
          const canvas = document.createElement("canvas");
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext("2d");
          if (!ctx) {
            return resolve({ base64: e.target.result, mimeType: file.type || "image/jpeg" });
          }
          ctx.fillStyle = "#FFFFFF";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(img, 0, 0, width, height);
          const compressedBase64 = canvas.toDataURL("image/jpeg", quality);
          resolve({
            base64: compressedBase64,
            mimeType: "image/jpeg",
            width,
            height
          });
        };
        img.onerror = () => reject(new Error("이미지 로딩에 실패했습니다."));
        img.src = e.target.result;
      };
      reader.onerror = () => reject(new Error("파일 읽기에 실패했습니다."));
      reader.readAsDataURL(file);
    });
  }
